/* ================= MBA Core track: missions ================= */
addMissions([
{id:'m01',track:'mba',title:'Reading the three statements',mins:35,blurb:'Income statement, balance sheet and cash flow — and the links that tie them together.',
 lab:{key:'three',name:'Linked three-statement model',intro:'Change any driver and watch profit, cash and the balance sheet move together.'},
 cards:[
  {h:'Three views of one business',b:`<ul><li><b>Income statement:</b> performance over a period (revenue − costs = profit).</li><li><b>Balance sheet:</b> position at a point in time (assets = liabilities + equity).</li><li><b>Cash flow statement:</b> where cash actually came from and went (operating, investing, financing).</li></ul>`},
  {h:'Profit is not cash',b:`<p>Revenue is booked when earned, not when collected. Costs are matched to revenue, not paid when incurred. Depreciation reduces profit but uses no cash. So a profitable company can run out of cash — and a loss-making one can be cash-rich.</p>`},
  {h:'The links',b:`<div class="formula">Net income → retained earnings (balance sheet) and → top of the cash flow statement<br>Operating cash flow = Net income + D&A − Δ working capital<br>Free cash flow = Operating cash flow − Capex<br>Ending cash (cash flow) = Cash on the balance sheet</div>`},
  {h:'Working capital',b:`<p>Receivables + inventory − payables. When it grows, cash is absorbed; when it shrinks, cash is released. Fast-growing companies often burn cash in working capital even with good margins.</p>`},
  {h:'How consultants read accounts fast',b:`<ol><li>Revenue growth and gross margin trend</li><li>Operating margin and where costs grew</li><li>Operating cash flow vs net income (quality of earnings)</li><li>Capex vs depreciation (investing or harvesting?)</li><li>Debt and liquidity</li></ol>`}],
 quiz:[
  {q:'Which statement shows a company\'s position at a point in time?',o:['Income statement','Balance sheet','Cash flow statement','Notes'],a:1,w:'The balance sheet is a snapshot; the other two cover a period.'},
  {q:'Net income 50, depreciation 20, working capital up 15. Operating cash flow?',o:['85','55','35','65'],a:1,w:'50 + 20 − 15 = 55.'},
  {q:'Why is depreciation added back in the cash flow statement?',o:['It is a tax','It reduced profit but used no cash this year','It is a financing item','It is always zero'],a:1,w:'The cash went out when the asset was bought (capex).'},
  {q:'A fast-growing company has rising profits but falling cash. Most likely cause?',o:['Too much depreciation','Working capital absorbing cash','Low taxes','High dividends only'],a:1,w:'Receivables and inventory grow with sales, tying up cash.'},
  {q:'Operating cash flow 60, capex 75. Free cash flow?',o:['135','−15','15','60'],a:1,w:'60 − 75 = −15: the business is investing more than it generates.'},
  {q:'Operating cash flow consistently below net income is a sign to check…',o:['Nothing','Earnings quality: revenue recognition, receivables, inventory','The tax rate','Share count'],a:1,w:'Profits that never turn into cash deserve scrutiny.'}],
 srs:[{q:'Operating cash flow (indirect method)?',a:'Net income + D&A − increase in working capital.'},{q:'Free cash flow?',a:'Operating cash flow − capex.'},{q:'Balance sheet identity?',a:'Assets = Liabilities + Equity.'},{q:'Why can a profitable firm run out of cash?',a:'Profit is accrual-based; growth in receivables/inventory and capex absorb cash.'}],
 read:[{t:'Financial statements',s:'Investopedia',n:'Clear primer on the three statements',u:INV('f/financial-statements.asp')},{t:'MIT OCW: financial accounting',s:'MIT OpenCourseWare',u:OCW('financial accounting')},{t:'Free cash flow',s:'Investopedia',u:INV('f/freecashflow.asp')}]},

{id:'m02',track:'mba',title:'Working capital and the cash cycle',mins:30,blurb:'How many days cash is stuck between paying suppliers and collecting from customers.',
 lab:{key:'ccc',name:'Cash-conversion-cycle calculator',intro:'Move DSO, DIO and DPO; see how much cash you release.'},
 cards:[
  {h:'The cash conversion cycle',b:`<div class="formula">CCC = DSO + DIO − DPO</div><ul><li><b>DSO</b> days sales outstanding = receivables ÷ revenue × 365</li><li><b>DIO</b> days inventory outstanding = inventory ÷ COGS × 365</li><li><b>DPO</b> days payables outstanding = payables ÷ COGS × 365</li></ul>`},
  {h:'What a day is worth',b:`<p>One day of DSO = revenue ÷ 365. One day of DIO or DPO = COGS ÷ 365. For a SAR 800m business, cutting DSO by 10 days releases about SAR 22m of cash — permanently, while volumes hold.</p>`},
  {h:'Levers',b:`<ul><li><b>DSO:</b> invoice faster, clear disputes, credit policy, early-payment discounts, e-invoicing.</li><li><b>DIO:</b> SKU rationalisation, better forecasts, safety-stock tuning, VMI.</li><li><b>DPO:</b> negotiate terms, supply-chain finance — without squeezing small suppliers.</li></ul>`},
  {h:'Negative cycles',b:`<p>Some businesses collect before they pay: supermarkets, airlines, many subscription businesses. A negative CCC means growth <i>funds itself</i>. Manufacturers usually have long positive cycles.</p>`},
  {h:'Context matters',b:`<p>Government and giga-project customers in the Gulf can pay slowly, which inflates DSO for contractors. Before comparing to peers, check customer mix and contract terms.</p>`}],
 quiz:[
  {q:'DSO 50, DIO 60, DPO 40. CCC?',o:['150','70','30','110'],a:1,w:'50 + 60 − 40 = 70 days.'},
  {q:'Revenue SAR 365m. Value of a 1-day DSO cut?',o:['SAR 1m','SAR 365m','SAR 0.1m','SAR 10m'],a:0,w:'365 / 365 = SAR 1m per day.'},
  {q:'A negative CCC means…',o:['The firm is insolvent','It collects from customers before paying suppliers','Inventory is negative','Sales are falling'],a:1,w:'Typical of supermarkets: suppliers fund the working capital.'},
  {q:'DIO is calculated on…',o:['Revenue','Cost of goods sold','Total assets','Net income'],a:1,w:'Inventory is held at cost, so use COGS.'},
  {q:'Which DSO lever risks hurting customer relationships least?',o:['Charging penalty interest immediately','Invoicing on time and resolving disputes fast','Stopping deliveries','Cutting credit for everyone'],a:1,w:'Many late payments come from slow or wrong invoices.'},
  {q:'Stretching DPO to 120 days with small suppliers may…',o:['Have no downside','Weaken suppliers and raise prices or risk','Lower COGS automatically','Reduce DSO'],a:1,w:'Cash is shifted, not created; fragile suppliers pay the cost.'}],
 srs:[{q:'CCC formula?',a:'DSO + DIO − DPO.'},{q:'DSO formula?',a:'Receivables ÷ revenue × 365.'},{q:'Value of one DIO day?',a:'COGS ÷ 365.'},{q:'What does a negative CCC mean?',a:'Customers pay before suppliers are paid; growth funds itself.'}],
 read:[{t:'Cash conversion cycle',s:'Investopedia',u:INV('c/cashconversioncycle.asp')},{t:'Working capital management',s:'HBR search',u:HBRS('working capital')},{t:'Working capital',s:'Investopedia',u:INV('w/workingcapital.asp')}]},

{id:'m03',track:'mba',title:'Ratio analysis and DuPont',mins:30,blurb:'Decompose return on equity into margin, efficiency and leverage.',
 lab:{key:'dupont',name:'DuPont ROE decomposer',intro:'Compare your company with a low-cost peer and raise ROE the healthy way.'},
 cards:[
  {h:'Four families of ratios',b:`<ul><li><b>Profitability:</b> gross, EBITDA, net margin; ROA, ROE, ROIC.</li><li><b>Efficiency:</b> asset turnover, DSO, DIO.</li><li><b>Liquidity:</b> current ratio, quick ratio.</li><li><b>Leverage:</b> debt/EBITDA, interest cover, debt/equity.</li></ul>`},
  {h:'DuPont',b:`<div class="formula">ROE = Net margin × Asset turnover × Leverage<br>= (NI/Revenue) × (Revenue/Assets) × (Assets/Equity)</div><p>Same ROE, different stories: luxury brands earn it through margin, discount retailers through turnover, banks through leverage.</p>`},
  {h:'ROIC',b:`<p>Return on invested capital = NOPAT ÷ (debt + equity − cash). It strips out financing choices and is the best single measure of operating value creation: value is created when ROIC > WACC.</p>`},
  {h:'Compare properly',b:`<p>Ratios mean little alone. Compare against the company's own history and peers with similar business models. Check accounting differences (leases, one-offs) before concluding.</p>`},
  {h:'Debt capacity',b:`<p>Lenders look at net debt/EBITDA (often comfortable below about 2–3×) and interest cover (EBIT ÷ interest). High leverage boosts ROE in good years and destroys it in bad ones.</p>`}],
 quiz:[
  {q:'Margin 5%, turnover 2×, leverage 2×. ROE?',o:['9%','20%','10%','40%'],a:1,w:'0.05 × 2 × 2 = 0.20.'},
  {q:'Which DuPont driver reflects financing rather than operations?',o:['Net margin','Asset turnover','Leverage','None'],a:2,w:'Assets/equity rises with borrowing.'},
  {q:'Value is created when…',o:['ROE > 10%','ROIC > WACC','Revenue grows','Debt is zero'],a:1,w:'Returns above the cost of capital create value.'},
  {q:'A discount retailer typically has…',o:['High margin, low turnover','Low margin, high turnover','High leverage only','No inventory'],a:1,w:'Thin margins, fast-moving assets.'},
  {q:'Interest cover is…',o:['Debt ÷ equity','EBIT ÷ interest expense','Cash ÷ debt','Interest ÷ revenue'],a:1,w:'How many times profit covers interest.'},
  {q:'ROE jumped because the firm took on more debt. This is…',o:['Better operations','Higher financial risk','Higher margin','Higher turnover'],a:1,w:'Leverage-driven ROE is riskier, not better.'}],
 srs:[{q:'DuPont formula?',a:'ROE = margin × asset turnover × leverage.'},{q:'ROIC?',a:'NOPAT ÷ invested capital; create value when ROIC > WACC.'},{q:'Net debt/EBITDA measures?',a:'Years of EBITDA needed to repay net debt; a leverage gauge.'},{q:'Interest cover?',a:'EBIT ÷ interest expense.'}],
 read:[{t:'Return on equity and DuPont analysis',s:'HBR search',u:HBRS('return on equity')},{t:'DuPont analysis',s:'Investopedia',u:INV('d/dupontanalysis.asp')},{t:'Return on invested capital',s:'Investopedia',u:INV('r/returnoninvestmentcapital.asp')}]},

{id:'m04',track:'mba',title:'Cost behaviour and break-even',mins:30,blurb:'Fixed vs variable costs, contribution margin and operating leverage.',
 lab:{key:'breakeven',name:'Break-even and contribution chart',intro:'See revenue and cost lines cross, then move price.'},
 cards:[
  {h:'Fixed and variable',b:`<p><b>Variable</b> costs move with volume (materials, energy per unit). <b>Fixed</b> costs don't, within a range (rent, salaries, depreciation). Semi-variable costs have both parts.</p>`},
  {h:'Contribution margin',b:`<div class="formula">Contribution per unit = Price − Variable cost<br>Break-even volume = Fixed costs ÷ Contribution per unit</div><p>Every unit above break-even adds its full contribution to profit.</p>`},
  {h:'Margin of safety',b:`<p>(Current volume − break-even) ÷ current volume. It tells you how far sales can fall before losses start — a quick risk gauge for any plan.</p>`},
  {h:'Operating leverage',b:`<div class="formula">DOL = Contribution ÷ Operating profit</div><p>High fixed costs mean high operating leverage: profits swing more than sales in both directions. Cement, airlines and steel are classic examples.</p>`},
  {h:'Use with care',b:`<p>Break-even assumes constant price and unit cost. Real costs step up (a new shift, a new line) and price may need to fall to sell more. Use it for direction and sanity checks.</p>`}],
 quiz:[
  {q:'Price 40, variable cost 25, fixed 300k. Break-even units?',o:['12,000','20,000','7,500','30,000'],a:1,w:'300,000 ÷ 15 = 20,000.'},
  {q:'Margin of safety at 25,000 units in that example?',o:['20%','25%','80%','5%'],a:0,w:'(25,000 − 20,000) ÷ 25,000 = 20%.'},
  {q:'High operating leverage means…',o:['Low fixed costs','Profit swings more than sales','No debt','Stable profit'],a:1,w:'Fixed costs amplify changes in volume.'},
  {q:'Which is usually a fixed cost in a plant?',o:['Raw material','Packaging per unit','Plant manager salary','Energy per tonne'],a:2,w:'Salaries of overhead staff don\'t vary with each unit.'},
  {q:'Contribution 600k, operating profit 150k. DOL?',o:['4×','0.25×','450k','1.5×'],a:0,w:'600 ÷ 150 = 4: a 10% sales rise → about 40% profit rise.'},
  {q:'A key limitation of break-even analysis?',o:['It needs a computer','It assumes constant price and unit costs','It ignores revenue','It cannot be graphed'],a:1,w:'Real costs and prices change with volume.'}],
 srs:[{q:'Break-even volume?',a:'Fixed costs ÷ (price − variable cost per unit).'},{q:'Margin of safety?',a:'(Current volume − break-even) ÷ current volume.'},{q:'Degree of operating leverage?',a:'Contribution ÷ operating profit.'},{q:'Contribution margin?',a:'Price − variable cost per unit.'}],
 read:[{t:'Break-even analysis',s:'Investopedia',u:INV('b/breakevenanalysis.asp')},{t:'Operating leverage',s:'Investopedia',u:INV('o/operatingleverage.asp')},{t:'Cost behaviour',s:'MIT OCW search',u:OCW('managerial accounting')}]},

{id:'m05',track:'mba',title:'Time value of money',mins:35,blurb:'NPV, IRR and payback: how to judge an investment.',
 lab:{key:'npv',name:'NPV / IRR / payback calculator',intro:'Edit the cash flows and discount rate; find the IRR yourself.'},
 cards:[
  {h:'A riyal today beats a riyal tomorrow',b:`<p>Money today can be invested and earn a return, and the future is uncertain. So future cash is discounted.</p><div class="formula">PV = CF_t ÷ (1 + r)^t</div>`},
  {h:'Net present value',b:`<div class="formula">NPV = Σ CF_t ÷ (1 + r)^t − Investment</div><p>NPV > 0 means the project earns more than the cost of capital and creates value. It is the primary decision rule in corporate finance.</p>`},
  {h:'Internal rate of return',b:`<p>The discount rate at which NPV = 0. Accept if IRR > cost of capital. Easy to communicate, but misleading when comparing projects of different size or timing, or when cash flows change sign more than once.</p>`},
  {h:'Payback',b:`<p>Years to recover the investment. Simple and popular with CEOs because it captures liquidity and risk, but it ignores cash after payback and (unless discounted) the time value of money.</p>`},
  {h:'Rule of 72',b:`<p>Money doubles in roughly 72 ÷ interest rate years. At 8%, about 9 years. Useful for sanity checks in meetings.</p>`}],
 quiz:[
  {q:'PV of SAR 110 received in one year at 10%?',o:['100','110','121','90'],a:0,w:'110 ÷ 1.1 = 100.'},
  {q:'NPV > 0 means…',o:['IRR is below the cost of capital','The project returns more than the cost of capital','Payback is under 1 year','Revenue is positive'],a:1,w:'Positive NPV creates value at that discount rate.'},
  {q:'IRR is the rate at which…',o:['Payback is reached','NPV equals zero','Profit is highest','Debt is repaid'],a:1,w:'By definition.'},
  {q:'Two mutually exclusive projects: A has higher IRR, B higher NPV. Choose…',o:['A','B','Either','Neither'],a:1,w:'NPV measures value added; IRR ignores scale.'},
  {q:'At 6%, money doubles in about…',o:['6 years','12 years','18 years','24 years'],a:1,w:'72 ÷ 6 = 12.'},
  {q:'Main weakness of simple payback?',o:['Hard to compute','Ignores cash after payback and time value','Uses NPV','Requires IRR'],a:1,w:'A project could pay back fast and then lose money.'}],
 srs:[{q:'NPV decision rule?',a:'Accept if NPV > 0 at the cost of capital.'},{q:'IRR definition?',a:'Discount rate that makes NPV zero.'},{q:'Rule of 72?',a:'Doubling time ≈ 72 ÷ rate (%).'},{q:'When does IRR mislead?',a:'Comparing projects of different size/timing; cash flows with multiple sign changes.'}],
 read:[{t:'A Refresher on Net Present Value',s:'Harvard Business Review, 2014',u:'https://hbr.org/2014/11/a-refresher-on-net-present-value'},{t:'A Refresher on Internal Rate of Return',s:'Harvard Business Review, 2016',u:'https://hbr.org/2016/03/a-refresher-on-internal-rate-of-return'},{t:'MIT 15.401 Finance Theory I',s:'MIT OpenCourseWare',u:OCW('finance theory')}]},

{id:'m06',track:'mba',title:'Cost of capital',mins:35,blurb:'CAPM, WACC and why capital structure matters.',
 lab:{key:'wacc',name:'WACC and capital-structure builder',intro:'Relever beta, price debt, and find the WACC-minimising mix.'},
 cards:[
  {h:'The hurdle rate',b:`<p>WACC is the blended return investors require. Projects must beat it to create value. Use it as the discount rate for cash flows available to all capital providers.</p><div class="formula">WACC = E/V × Ke + D/V × Kd × (1 − t)</div>`},
  {h:'Cost of equity: CAPM',b:`<div class="formula">Ke = Rf + β × ERP</div><p>Rf: long-term government bond yield. β: sensitivity to the market. ERP: extra return investors demand for equities. For Saudi companies, practitioners debate whether to add a country risk premium.</p>`},
  {h:'Cost of debt',b:`<p>The yield the company would pay on new debt today, after tax because interest is deductible (for taxed entities; Saudi-owned firms pay zakat instead, which changes the shield).</p>`},
  {h:'Leverage changes beta',b:`<div class="formula">β levered = β unlevered × (1 + (1 − t) × D/E)</div><p>More debt makes equity riskier. Unlever peer betas, average them, then relever at your target structure.</p>`},
  {h:'The optimal structure',b:`<p>Debt is cheaper and tax-deductible, so WACC falls at first; then distress risk raises both Kd and Ke. The flat bottom of the curve is wide, so judgement and flexibility matter more than a precise optimum.</p>`}],
 quiz:[
  {q:'Rf 4%, β 1.2, ERP 6%. Cost of equity?',o:['11.2%','10%','7.2%','12%'],a:0,w:'4 + 1.2 × 6 = 11.2%.'},
  {q:'E/V 60%, Ke 12%; D/V 40%, Kd 6%, tax 20%. WACC?',o:['9.12%','9.6%','10%','8.4%'],a:0,w:'0.6×12 + 0.4×6×0.8 = 7.2 + 1.92 = 9.12%.'},
  {q:'Why is the cost of debt multiplied by (1 − t)?',o:['Debt is risk-free','Interest is tax-deductible','Equity is taxed','Convention only'],a:1,w:'The tax shield lowers the effective cost.'},
  {q:'Adding debt makes the levered beta…',o:['Fall','Rise','Unchanged','Zero'],a:1,w:'Equity holders bear more risk.'},
  {q:'A project with IRR 9% and WACC 10% should…',o:['Go ahead','Be rejected on financial grounds','Be financed with more debt','Be valued at IRR'],a:1,w:'It does not earn its cost of capital.'},
  {q:'Beyond the optimum, more debt raises WACC because…',o:['Taxes rise','Distress risk raises Kd and Ke','Equity becomes cheaper','Rf rises'],a:1,w:'Default risk outweighs the tax shield.'}],
 srs:[{q:'WACC formula?',a:'E/V·Ke + D/V·Kd·(1−t).'},{q:'CAPM?',a:'Ke = Rf + β × ERP.'},{q:'Relever beta?',a:'βL = βU × (1 + (1−t) × D/E).'},{q:'Why does WACC eventually rise with leverage?',a:'Financial distress risk raises both the cost of debt and of equity.'}],
 read:[{t:'A Refresher on Cost of Capital',s:'Harvard Business Review, 2015',u:'https://hbr.org/2015/04/a-refresher-on-cost-of-capital'},{t:'Damodaran Online: cost of capital data and notes',s:'NYU Stern',n:'Betas, ERPs and country risk premiums',u:DAMO},{t:'WACC',s:'Investopedia',u:INV('w/wacc.asp')}]},

{id:'m07',track:'mba',title:'DCF valuation',mins:45,blurb:'Value a business from its future free cash flows.',
 lab:{key:'dcf',name:'Five-year DCF with sensitivity grid',intro:'Build EV and value per share; see how much rides on WACC and terminal growth.'},
 cards:[
  {h:'The logic',b:`<p>A business is worth the present value of the cash it will generate for its investors. A DCF forecasts free cash flow, then discounts it at WACC.</p><div class="formula">FCF = EBIT × (1 − t) + D&A − Capex − Δ Working capital</div>`},
  {h:'Terminal value',b:`<div class="formula">TV = FCF₅ × (1 + g) ÷ (WACC − g)</div><p>Captures value beyond the forecast. g should not exceed long-run nominal economic growth. TV often makes up 60–80% of the total.</p>`},
  {h:'From enterprise to equity',b:`<div class="formula">Equity value = Enterprise value − Net debt (− minorities, + non-operating assets)<br>Value per share = Equity value ÷ Shares</div>`},
  {h:'Drivers that matter',b:`<p>Revenue growth, margin, capital intensity, WACC and terminal growth. A good DCF ties each to evidence: market growth, peer margins, capex plans. Always show a sensitivity table.</p>`},
  {h:'Triangulate',b:`<p>Check the DCF against trading multiples (EV/EBITDA of peers) and recent transactions. If they disagree widely, find out why before trusting either.</p>`}],
 quiz:[
  {q:'EBIT 100, tax 20%, D&A 15, capex 25, ΔNWC 10. FCF?',o:['60','80','70','100'],a:0,w:'80 + 15 − 25 − 10 = 60.'},
  {q:'FCF₅ 50, g 3%, WACC 10%. Terminal value?',o:['about 736','500','714','1,667'],a:0,w:'50 × 1.03 ÷ 0.07 ≈ 736.'},
  {q:'EV 2,000, net debt 500, 100m shares. Value per share?',o:['15','20','25','5'],a:0,w:'(2,000 − 500) ÷ 100 = 15.'},
  {q:'Terminal growth should generally be…',o:['Higher than WACC','Below long-run economic growth','Equal to revenue growth in year 1','Zero always'],a:1,w:'No firm can outgrow the economy forever.'},
  {q:'Which input usually moves DCF value the most?',o:['Share count','WACC and terminal growth','Tax rate','Year-1 capex'],a:1,w:'They drive the terminal value, the largest piece.'},
  {q:'Why triangulate with multiples?',o:['DCFs are illegal','To check the DCF against how the market prices peers','Multiples are always right','To avoid forecasting'],a:1,w:'Two independent views expose unrealistic assumptions.'}],
 srs:[{q:'Unlevered FCF?',a:'EBIT(1−t) + D&A − capex − ΔNWC.'},{q:'Gordon terminal value?',a:'FCF₅ × (1+g) ÷ (WACC − g).'},{q:'EV to equity?',a:'Equity = EV − net debt (adjust minorities, non-operating assets).'},{q:'Typical TV share of EV?',a:'Often 60–80%.'}],
 read:[{t:'Damodaran Online: valuation',s:'NYU Stern',u:DAMO},{t:'Discounted cash flow',s:'Investopedia',u:INV('d/dcf.asp')},{t:'MIT OCW: corporate finance',s:'MIT OpenCourseWare',u:OCW('corporate finance')}]},

{id:'m08',track:'mba',title:'Microeconomics for managers',mins:35,blurb:'Demand, elasticity, marginal thinking and market structure.',
 lab:{key:'micro',name:'Elasticity and profit-maximising price',intro:'Move the price along a demand curve and find the profit peak.'},
 cards:[
  {h:'Demand and elasticity',b:`<div class="formula">Price elasticity = % change in quantity ÷ % change in price</div><p>|e| > 1: elastic — raising price lowers revenue. |e| < 1: inelastic — raising price raises revenue. Necessities and products without substitutes are inelastic.</p>`},
  {h:'Think at the margin',b:`<p>Decisions depend on marginal revenue and marginal cost, not averages. Produce more while MR > MC. Ignore sunk costs: they are gone whatever you decide.</p>`},
  {h:'Market structures',b:`<ul><li><b>Perfect competition:</b> price takers, zero economic profit long-run.</li><li><b>Monopolistic competition:</b> differentiated products (cafés).</li><li><b>Oligopoly:</b> few players watch each other (telecoms, cement).</li><li><b>Monopoly:</b> price setter, often regulated.</li></ul>`},
  {h:'Opportunity cost',b:`<p>The true cost of anything is the best alternative you give up. A plant manager's hour on a low-value report costs the improvement project he did not run.</p>`},
  {h:'Game theory in one card',b:`<p>In oligopolies, each firm's best move depends on rivals'. Price wars often look like a prisoner's dilemma: everyone cutting price leaves everyone worse off. Signalling and differentiation help escape it.</p>`}],
 quiz:[
  {q:'Price rises 10%, quantity falls 20%. Elasticity?',o:['−0.5','−2','−20','−10'],a:1,w:'−20% ÷ 10% = −2: elastic.'},
  {q:'If demand is inelastic, raising price…',o:['Lowers revenue','Raises revenue','Has no effect','Lowers costs'],a:1,w:'Quantity falls proportionally less than price rises.'},
  {q:'A sunk cost should…',o:['Drive the decision','Be ignored in forward decisions','Be doubled','Be depreciated faster'],a:1,w:'Only future costs and benefits matter.'},
  {q:'Saudi cement with a few large producers is closest to…',o:['Perfect competition','Oligopoly','Monopoly','Monopolistic competition'],a:1,w:'Few players, interdependent pricing.'},
  {q:'Produce more while…',o:['Average cost falls','Marginal revenue > marginal cost','Price > average cost','Volume grows'],a:1,w:'The core marginal rule.'},
  {q:'The profit-maximising price (with positive marginal cost) is where demand is…',o:['Inelastic','Elastic','Unit elastic only by chance','Irrelevant'],a:1,w:'Otherwise raising price would increase profit.'}],
 srs:[{q:'Price elasticity?',a:'%ΔQ ÷ %ΔP.'},{q:'Elastic vs inelastic?',a:'|e|>1 elastic (price up → revenue down); |e|<1 inelastic.'},{q:'Marginal rule?',a:'Expand while MR > MC; profit max at MR = MC.'},{q:'Opportunity cost?',a:'Value of the best alternative forgone.'}],
 read:[{t:'A Refresher on Price Elasticity',s:'Harvard Business Review, 2015',u:'https://hbr.org/2015/08/a-refresher-on-price-elasticity'},{t:'MIT 15.010 Economic Analysis for Business Decisions',s:'MIT OpenCourseWare',u:OCW('economic analysis for business decisions')},{t:'Kellogg Insight: economics',s:'Kellogg School of Management',u:'https://insight.kellogg.northwestern.edu/'}]},

{id:'m09',track:'mba',title:'Macroeconomics and the Saudi economy',mins:35,blurb:'GDP, inflation, rates, the peg and the fiscal break-even.',
 lab:{key:'macro',name:'Oil, budget and rates scenario model',intro:'An illustrative model of how oil and policy flow into the budget and sectors.'},
 cards:[
  {h:'GDP in three ways',b:`<p>Output (what is produced), expenditure (C + I + G + X − M) and income (wages + profits). Saudi statistics also split <b>oil</b> and <b>non-oil</b> GDP; non-oil growth is the diversification yardstick.</p>`},
  {h:'The peg',b:`<p>The riyal has been pegged to the US dollar at 3.75 since 1986. So SAMA's policy rate broadly follows the US Federal Reserve. Monetary policy is imported; fiscal policy does most of the work.</p>`},
  {h:'Fiscal break-even',b:`<p>The oil price at which the government budget balances. It depends on production, spending and non-oil revenue. Higher non-oil revenue (VAT, fees, dividends) lowers it — the logic of diversification.</p>`},
  {h:'Inflation and rates',b:`<p>Inflation erodes purchasing power; central banks raise rates to cool it. Higher rates raise mortgage and corporate borrowing costs and lower asset valuations (higher discount rates).</p>`},
  {h:'Reading the cycle for clients',b:`<p>Ask: where are oil prices, rates and government spending heading, and which client sectors depend on each? Contractors track project awards; retailers track consumer spending; banks track rates and credit growth.</p>`}],
 quiz:[
  {q:'Why does SAMA\'s policy rate follow the Fed?',o:['Law requires it','The riyal is pegged to the dollar','Oil is priced in riyals','Coincidence'],a:1,w:'Keeping the peg requires aligned interest rates.'},
  {q:'Non-oil revenue rises. The fiscal break-even oil price…',o:['Rises','Falls','Unchanged','Doubles'],a:1,w:'Less oil money is needed to balance spending.'},
  {q:'GDP by expenditure is…',o:['C + I + G + X − M','Wages + profits only','Oil output only','Exports − imports'],a:0,w:'Consumption, investment, government, net exports.'},
  {q:'Higher interest rates usually…',o:['Raise asset valuations','Lower valuations and raise borrowing costs','Lower inflation instantly','Raise oil prices'],a:1,w:'Higher discount rates and costlier credit.'},
  {q:'Which indicator best tracks diversification?',o:['Oil GDP','Non-oil GDP growth','Oil price','Population'],a:1,w:'It shows the economy growing beyond oil.'},
  {q:'A contractor client is most sensitive to…',o:['Mortgage rates only','Government project awards and payment timing','The peg level','Tourism visas'],a:1,w:'Public spending drives their order book and cash.'}],
 srs:[{q:'GDP expenditure identity?',a:'C + I + G + (X − M).'},{q:'Riyal peg?',a:'SAR 3.75 = USD 1 since 1986; policy rates track the Fed.'},{q:'Fiscal break-even oil price?',a:'Oil price at which the budget balances; falls as non-oil revenue rises.'},{q:'Effect of higher rates?',a:'Costlier credit, lower asset valuations, cooler demand.'}],
 read:[{t:'IMF: Saudi Arabia country page',s:'International Monetary Fund',n:'Article IV reports and data',u:'https://www.imf.org/en/Countries/SAU'},{t:'Saudi Central Bank (SAMA)',s:'SAMA',u:'https://www.sama.gov.sa/'},{t:'Ministry of Finance: budget statements',s:'Saudi Ministry of Finance',u:'https://www.mof.gov.sa/'}]},

{id:'m10',track:'mba',title:'Pricing strategy',mins:35,blurb:'Value-based pricing, segmentation and good-better-best tiers.',
 lab:{key:'tiers',name:'Pricing simulator: one price vs tiers',intro:'Three segments, two products. Beat the best single price.'},
 cards:[
  {h:'Price is the strongest lever',b:`<p>For a typical company, a 1% price increase raises operating profit far more than a 1% cost cut or volume gain, because it falls straight to the bottom line.</p>`},
  {h:'Willingness to pay varies',b:`<p>Customers value the same product differently. One price leaves money on the table with high-value customers and loses low-value ones. Segmentation captures more of the value curve.</p>`},
  {h:'Price discrimination, legally',b:`<ul><li>Versions and tiers (good / better / best)</li><li>Bundles</li><li>Time-based (peak / off-peak)</li><li>Volume and loyalty discounts</li><li>Channel or region pricing</li></ul>`},
  {h:'Self-selection',b:`<p>Tiers work when each segment prefers its own tier. The premium must be worth the extra to premium buyers, and the basic must not be so good that they trade down (cannibalisation).</p>`},
  {h:'The pocket price waterfall',b:`<p>List price minus discounts, rebates, payment terms and freight gives the pocket price — what you really get. Leakage there is often the fastest pricing win.</p>`}],
 quiz:[
  {q:'Why does price have outsized profit impact?',o:['It changes volume','It carries no extra cost, so it falls to profit','It lowers costs','It is regulated'],a:1,w:'Same costs, more revenue.'},
  {q:'Good-better-best pricing works by…',o:['Lowering all prices','Letting segments self-select into tiers','Raising costs','Removing choice'],a:1,w:'Each segment picks the tier that fits its value.'},
  {q:'Cannibalisation in tiering means…',o:['Competitors copy you','High-value customers trade down to the cheap tier','Prices fall','Costs rise'],a:1,w:'The basic tier is too attractive to premium buyers.'},
  {q:'The pocket price is…',o:['List price','What remains after all discounts and costs to serve','Competitor price','Cost price'],a:1,w:'It reveals leakage between list and reality.'},
  {q:'Which is NOT a common way to segment price?',o:['Versions','Time of use','Random daily prices for identical customers','Bundles'],a:2,w:'Arbitrary pricing damages trust.'},
  {q:'A premium tier should be priced so that…',o:['Everyone buys it','Its target segment prefers it to Basic','It is cheaper than Basic','It matches cost'],a:1,w:'Respect the self-selection constraint.'}],
 srs:[{q:'Self-selection constraint?',a:'Each segment must prefer its own tier (value − price is highest there).'},{q:'Pocket price waterfall?',a:'List price minus discounts, rebates, terms, freight = realised price.'},{q:'Ways to segment price?',a:'Versions/tiers, bundles, time, volume, channel/region.'},{q:'Why tiers beat one price?',a:'They capture more of each segment\'s willingness to pay.'}],
 read:[{t:'The power of pricing',s:'McKinsey Quarterly',u:'https://www.mckinsey.com/capabilities/growth-marketing-and-sales/our-insights/the-power-of-pricing'},{t:'Pricing strategy',s:'HBR search',u:HBRS('pricing strategy')},{t:'Knowledge at Wharton: marketing',s:'The Wharton School',u:'https://knowledge.wharton.upenn.edu/'}]},

{id:'m11',track:'mba',title:'Marketing: STP and the 4Ps',mins:30,blurb:'Segment, target, position — then design the marketing mix.',
 lab:{key:'position',name:'Positioning-map builder',intro:'Find white space among Riyadh coffee chains and write a positioning statement.'},
 cards:[
  {h:'STP',b:`<ul><li><b>Segmentation:</b> split the market by needs, behaviour, demographics or geography.</li><li><b>Targeting:</b> pick segments you can serve profitably and win.</li><li><b>Positioning:</b> the distinct place you want in the target customer's mind.</li></ul>`},
  {h:'Good segments are…',b:`<p>Measurable, sizeable, reachable, different in their response, and actionable. "Young people" is weak; "office workers in Riyadh who buy coffee on the commute" is useful.</p>`},
  {h:'Positioning statement',b:`<div class="formula">For [target] who [need], [brand] is the [category] that [key benefit], unlike [main alternative], because [reason to believe].</div>`},
  {h:'The 4Ps',b:`<ul><li><b>Product:</b> features, quality, range.</li><li><b>Price:</b> level, tiers, promotions.</li><li><b>Place:</b> channels and coverage.</li><li><b>Promotion:</b> message and media.</li></ul><p>Services add People, Process and Physical evidence (7Ps).</p>`},
  {h:'Marketing myopia',b:`<p>Levitt's warning: define your business by the customer need, not the product. Railways thought they were in trains, not transport. Ask "what job is the customer hiring us for?"</p>`}],
 quiz:[
  {q:'The order of STP is…',o:['Target, Segment, Position','Segment, Target, Position','Position, Segment, Target','Price, Product, Place'],a:1,w:'Divide the market, choose, then position.'},
  {q:'Which segment description is most actionable?',o:['Everyone','Young people','Riyadh office workers buying coffee on the commute','People who like coffee'],a:2,w:'Specific need, place and behaviour.'},
  {q:'The 4Ps are…',o:['Plan, Prepare, Pitch, Profit','Product, Price, Place, Promotion','People, Process, Price, Product','Profit, Product, Promotion, Partners'],a:1,w:'The classic marketing mix.'},
  {q:'"Marketing myopia" warns against…',o:['Spending on ads','Defining the business by product instead of customer need','Segmenting','Pricing high'],a:1,w:'Levitt, 1960.'},
  {q:'White space on a positioning map is only valuable if…',o:['It is empty','There is real customer demand in it','It is premium','Competitors are big'],a:1,w:'Some spaces are empty because nobody wants them.'},
  {q:'A positioning statement should include…',o:['Every feature','Target, need, benefit and how you differ','Only the price','The logo'],a:1,w:'Clear, specific and differentiated.'}],
 srs:[{q:'STP?',a:'Segmentation, Targeting, Positioning.'},{q:'4Ps?',a:'Product, Price, Place, Promotion (+ People, Process, Physical evidence for services).'},{q:'Positioning statement template?',a:'For [target] who [need], [brand] is the [category] that [benefit], unlike [alternative], because [reason].'},{q:'Marketing myopia?',a:'Defining the business by product rather than customer need.'}],
 read:[{t:'Marketing Myopia',s:'Harvard Business Review',n:'Theodore Levitt',u:'https://hbr.org/2004/07/marketing-myopia'},{t:'Know Your Customers\' Jobs to Be Done',s:'Harvard Business Review, 2016',u:'https://hbr.org/2016/09/know-your-customers-jobs-to-be-done'},{t:'Kellogg Insight: marketing',s:'Kellogg School of Management',u:'https://insight.kellogg.northwestern.edu/'}]},

{id:'m12',track:'mba',title:'Competitive strategy: Five Forces',mins:35,blurb:'Why some industries earn more than others, and what to do about it.',
 lab:{key:'porter',name:'Five Forces builder',intro:'Rate the forces for three Saudi industries and write the "so what".'},
 cards:[
  {h:'Industry structure drives profit',b:`<p>Porter: average profitability differs by industry because of five forces. Strong forces squeeze profit; weak forces leave room for it.</p>`},
  {h:'The five forces',b:`<ol><li>Rivalry among existing competitors</li><li>Threat of new entrants (barriers: scale, licences, capital, brand)</li><li>Bargaining power of buyers</li><li>Bargaining power of suppliers</li><li>Threat of substitutes</li></ol>`},
  {h:'Not a checklist',b:`<p>The value is in the "so what": which force is strongest, is it changing, and how can a company position itself where the forces are weakest — or reshape them (switching costs, contracts, integration)?</p>`},
  {h:'What is strategy?',b:`<p>Porter also argues strategy is choosing a unique, valuable position with trade-offs and fit. Operational effectiveness (doing the same things better) is necessary but not strategy.</p>`},
  {h:'Government as a force',b:`<p>In the Kingdom, regulation, licensing, local-content rules and public procurement shape all five forces. Many analysts add it explicitly for Gulf markets.</p>`}],
 quiz:[
  {q:'Which is NOT one of the five forces?',o:['Buyer power','Threat of substitutes','Company culture','Supplier power'],a:2,w:'Culture is internal, not industry structure.'},
  {q:'High barriers to entry make an industry…',o:['Less attractive','More attractive for incumbents','Irrelevant','More competitive'],a:1,w:'Fewer new rivals protect margins.'},
  {q:'Contractors switch cement suppliers on price. That signals strong…',o:['Supplier power','Buyer power','Substitutes','Entry'],a:1,w:'Buyers with alternatives push prices down.'},
  {q:'Porter distinguishes strategy from…',o:['Marketing','Operational effectiveness','Finance','HR'],a:1,w:'Doing things better is not the same as being different.'},
  {q:'Video calls replacing business travel is an example of…',o:['Rivalry','Substitutes','Supplier power','Entry'],a:1,w:'A different product meeting the same need.'},
  {q:'The most valuable output of a Five Forces analysis is…',o:['The scores','The strategic implication of the strongest forces','A chart','The list of competitors'],a:1,w:'Always end with "so what".'}],
 srs:[{q:'The five forces?',a:'Rivalry, new entrants, buyer power, supplier power, substitutes.'},{q:'Strategy vs operational effectiveness?',a:'Strategy = unique position with trade-offs; OE = doing the same things better.'},{q:'Barriers to entry examples?',a:'Scale, capital, licences, brand, access to channels, switching costs.'},{q:'Extra force often added in Gulf markets?',a:'Government: regulation, licensing, local content, procurement.'}],
 read:[{t:'The Five Competitive Forces That Shape Strategy',s:'Harvard Business Review, 2008',u:'https://hbr.org/2008/01/the-five-competitive-forces-that-shape-strategy'},{t:'What Is Strategy?',s:'Harvard Business Review, 1996',u:'https://hbr.org/1996/11/what-is-strategy'},{t:'The Coherence Premium',s:'Harvard Business Review, 2010',u:'https://hbr.org/2010/06/the-coherence-premium'}]},

{id:'m13',track:'mba',title:'Growth strategy: BCG and Ansoff',mins:35,blurb:'Manage a portfolio and choose where to grow.',
 lab:{key:'bcg',name:'BCG matrix plotter + Ansoff drill',intro:'Plot a group\'s businesses, then classify growth options.'},
 cards:[
  {h:'BCG growth-share matrix',b:`<ul><li><b>Stars:</b> high growth, high share — invest.</li><li><b>Cash cows:</b> low growth, high share — harvest cash.</li><li><b>Question marks:</b> high growth, low share — invest selectively or exit.</li><li><b>Dogs:</b> low growth, low share — fix, sell or close.</li></ul>`},
  {h:'Relative market share',b:`<p>Your share ÷ largest competitor's share. Above 1× means you lead. BCG's logic: leaders have experience-curve cost advantages, so share predicts cash generation.</p>`},
  {h:'Ansoff matrix',b:`<div class="tablewrap"><table class="t"><tr><th></th><th>Existing products</th><th>New products</th></tr><tr><td>Existing markets</td><td>Market penetration</td><td>Product development</td></tr><tr><td>New markets</td><td>Market development</td><td>Diversification</td></tr></table></div><p>Risk rises as you move away from the core.</p>`},
  {h:'Adjacencies',b:`<p>The most successful growth usually comes from strong cores and adjacent moves sharing customers, capabilities or channels — not from leaps into unrelated businesses.</p>`},
  {h:'Limits',b:`<p>Both matrices are simplifications. Market definition changes the answer; cash cows can be disrupted; dogs can be profitable niches. Use them to start the conversation, not end it.</p>`}],
 quiz:[
  {q:'High growth, low relative share is a…',o:['Star','Cash cow','Question mark','Dog'],a:2,w:'Needs investment to win share, or an exit.'},
  {q:'Cash cows should mainly…',o:['Receive heavy investment','Generate cash for the portfolio','Be closed','Be merged'],a:1,w:'Harvest and fund stars and question marks.'},
  {q:'Selling existing products in a new country is…',o:['Market penetration','Product development','Market development','Diversification'],a:2,w:'Same product, new market.'},
  {q:'Riskiest Ansoff quadrant?',o:['Penetration','Product development','Market development','Diversification'],a:3,w:'New product and new market at once.'},
  {q:'Relative share of 0.5× means…',o:['You lead the market','Your share is half the leader\'s','50% market share','Half the growth'],a:1,w:'It compares you with the largest rival.'},
  {q:'A key limitation of the BCG matrix?',o:['Too complex','Results depend heavily on market definition','No visuals','Ignores growth'],a:1,w:'Define the market differently and quadrants shift.'}],
 srs:[{q:'BCG quadrants?',a:'Star (invest), Cash cow (harvest), Question mark (decide), Dog (fix/exit).'},{q:'Relative market share?',a:'Your share ÷ largest competitor\'s share.'},{q:'Ansoff quadrants?',a:'Penetration, product development, market development, diversification.'},{q:'Safest growth path?',a:'Strong core plus adjacencies sharing customers or capabilities.'}],
 read:[{t:'Strategies for Diversification',s:'Harvard Business Review, 1957',n:'Ansoff\'s original article',u:'https://hbr.org/1957/09/strategies-for-diversification'},{t:'The growth-share matrix',s:'BCG',u:'https://www.bcg.com/about/overview/our-history/growth-share-matrix'},{t:'Growth strategy',s:'HBR search',u:HBRS('growth strategy adjacencies')}]},

{id:'m14',track:'mba',title:'Operations strategy and process analysis',mins:30,blurb:'Capacity, bottlenecks, Little\'s Law and the operations–strategy fit.',
 lab:{key:'process',name:'Process-flow capacity analyser',intro:'Find the bottleneck and apply Little\'s Law.'},
 cards:[
  {h:'Operations as strategy',b:`<p>Operations should be designed for how the company competes: cost, quality, speed, flexibility or innovation. You cannot be best at all five; trade-offs are a strategic choice.</p>`},
  {h:'Process analysis',b:`<p>Map the steps, measure each step's capacity, and find the bottleneck — the slowest step sets the throughput of the whole process. Improving a non-bottleneck adds nothing.</p>`},
  {h:'Little\'s Law',b:`<div class="formula">WIP = Throughput × Flow time</div><p>Holds for any stable process. To cut lead time, raise throughput at the bottleneck or reduce work-in-process.</p>`},
  {h:'Utilisation and queues',b:`<p>As utilisation approaches 100%, waiting time explodes (variability creates queues). That is why hospitals, call centres and lines need some slack.</p>`},
  {h:'Product-process fit',b:`<p>Low-volume custom products suit job shops; high-volume standard products suit lines and continuous flow. Mismatches create cost or flexibility problems — a link to your engineering track.</p>`}],
 quiz:[
  {q:'Steps with capacities 40, 30, 50 per hour. Process capacity?',o:['40','30','50','120'],a:1,w:'The bottleneck sets the pace.'},
  {q:'WIP 60, throughput 20 per hour. Flow time?',o:['3 hours','1,200 hours','40 hours','0.33 hours'],a:0,w:'60 ÷ 20 = 3.'},
  {q:'Improving a non-bottleneck step…',o:['Raises throughput','Adds no throughput','Always lowers cost','Removes WIP'],a:1,w:'The bottleneck still limits output.'},
  {q:'Why keep utilisation below 100%?',o:['To waste capacity','Queues grow sharply with variability near full utilisation','Regulation','Lower quality'],a:1,w:'Some slack keeps lead times stable.'},
  {q:'A company competing on speed should prioritise…',o:['Lowest unit cost at all times','Short lead times and responsive capacity','Maximum inventory','Longest production runs'],a:1,w:'Operations must fit the competitive priority.'},
  {q:'Little\'s Law applies to…',o:['Factories only','Any stable process: hospitals, banks, factories','Inventory only','Finance only'],a:1,w:'It is general.'}],
 srs:[{q:'Little\'s Law?',a:'WIP = Throughput × Flow time.'},{q:'Bottleneck?',a:'The step with the lowest capacity; it sets process throughput.'},{q:'Five competitive priorities of operations?',a:'Cost, quality, speed, flexibility, innovation.'},{q:'Utilisation and waiting?',a:'Waiting time rises sharply as utilisation approaches 100% under variability.'}],
 read:[{t:'Little\'s law',s:'Wikipedia',u:'https://en.wikipedia.org/wiki/Little%27s_law'},{t:'Decoding the DNA of the Toyota Production System',s:'Harvard Business Review, 1999',u:'https://hbr.org/1999/09/decoding-the-dna-of-the-toyota-production-system'},{t:'MIT OCW: operations management',s:'MIT OpenCourseWare',u:OCW('operations management')}]},

{id:'m15',track:'mba',title:'Organisational behaviour',mins:30,blurb:'Motivation, teams, influence and managing up.',
 lab:{key:'sjt',name:'Situational judgement drill',intro:'Six realistic consulting situations. Pick the best response.'},
 cards:[
  {h:'Motivation',b:`<p>Herzberg: pay and conditions (hygiene factors) prevent dissatisfaction, but achievement, recognition and the work itself motivate. Pink's summary: autonomy, mastery, purpose.</p>`},
  {h:'Teams that work',b:`<p>Clear goals, clear roles, psychological safety (people can raise problems without fear), and regular feedback. Most team conflict starts with unclear ownership.</p>`},
  {h:'Influence without authority',b:`<p>Credibility (expertise and relationships), framing around the other person's goals, vivid evidence, and emotional connection (Conger). Consultants influence clients they cannot instruct.</p>`},
  {h:'Emotional intelligence',b:`<p>Goleman: self-awareness, self-regulation, motivation, empathy and social skill distinguish effective leaders more than IQ once a threshold is met.</p>`},
  {h:'Managing up',b:`<p>Understand your manager's goals, pressures and style; adapt (reader or listener?); raise issues early with options; keep promises. Your manager is your most important stakeholder.</p>`}],
 quiz:[
  {q:'According to Herzberg, salary is mainly a…',o:['Motivator','Hygiene factor','Leadership trait','Team role'],a:1,w:'Its absence demotivates; more of it rarely motivates for long.'},
  {q:'Psychological safety means…',o:['No deadlines','People can speak up about problems without fear','Everyone agrees','Job security'],a:1,w:'Edmondson\'s research links it to team learning.'},
  {q:'Best first move in a team conflict about workload?',o:['Escalate','Clarify roles and hand-offs','Do it yourself','Ignore it'],a:1,w:'Most conflicts are about ownership.'},
  {q:'Influence without authority starts with…',o:['Pressure','Credibility and the other person\'s goals','Rank','Email volume'],a:1,w:'People follow those they trust, toward goals they share.'},
  {q:'Which is NOT one of Goleman\'s EI components?',o:['Empathy','Self-regulation','IQ','Social skill'],a:2,w:'IQ is separate from emotional intelligence.'},
  {q:'A problem will make you miss a deadline. Best action?',o:['Tell your manager early with options','Hope to catch up','Explain after the deadline','Ask a peer to cover silently'],a:0,w:'No surprises.'}],
 srs:[{q:'Herzberg\'s two factors?',a:'Hygiene (pay, conditions) prevent dissatisfaction; motivators (achievement, recognition, work) drive motivation.'},{q:'Psychological safety?',a:'Shared belief that it is safe to speak up and take interpersonal risks.'},{q:'Goleman\'s EI components?',a:'Self-awareness, self-regulation, motivation, empathy, social skill.'},{q:'Pink\'s drivers of motivation?',a:'Autonomy, mastery, purpose.'}],
 read:[{t:'One More Time: How Do You Motivate Employees?',s:'Harvard Business Review',n:'Herzberg',u:'https://hbr.org/2003/01/one-more-time-how-do-you-motivate-employees'},{t:'What Makes a Leader?',s:'Harvard Business Review',n:'Goleman',u:'https://hbr.org/2004/01/what-makes-a-leader'},{t:'Managing Your Boss',s:'Harvard Business Review',u:'https://hbr.org/2005/01/managing-your-boss'}]},

{id:'m16',track:'mba',title:'Data analysis for decisions',mins:35,blurb:'Regression, significance and A/B tests — and how not to be fooled.',
 lab:{key:'stats',name:'Regression and A/B-test tool',intro:'Fit a line to data, then test whether a page change really worked.'},
 cards:[
  {h:'Describe before you model',b:`<p>Look at the data: mean vs median (skew), spread, outliers, missing values, and a plot. Many wrong conclusions come from never charting the raw numbers.</p>`},
  {h:'Regression',b:`<div class="formula">y = a + b·x · R² = share of variance explained</div><p>The slope estimates how y changes with x. A high R² does not prove causation: something else may drive both.</p>`},
  {h:'Significance',b:`<p>A p-value is the probability of seeing a result at least this extreme if there were no real effect. Below 0.05 is the common threshold — but statistical significance is not business significance; check the size of the effect.</p>`},
  {h:'A/B tests',b:`<p>Randomly split traffic, change one thing, measure the outcome. Decide the sample size and stopping rule in advance; peeking and stopping early inflates false positives.</p>`},
  {h:'Common traps',b:`<ul><li>Correlation ≠ causation</li><li>Survivorship bias (only looking at winners)</li><li>Simpson's paradox (trends reverse when groups are combined)</li><li>Small samples</li></ul>`}],
 quiz:[
  {q:'R² of 0.8 means…',o:['x causes y','80% of y\'s variance is explained by the model','80% of points lie on the line','The slope is 0.8'],a:1,w:'It measures fit, not causation.'},
  {q:'p = 0.03 means…',o:['3% chance the effect is real','If there were no effect, a result this extreme would occur about 3% of the time','The effect is 3%','The test failed'],a:1,w:'The correct interpretation of a p-value.'},
  {q:'Ice-cream sales and drownings correlate. Most likely…',o:['Ice cream causes drowning','A third factor (hot weather) drives both','Drowning causes ice-cream sales','Coincidence'],a:1,w:'Confounding variable.'},
  {q:'Why decide A/B sample size in advance?',o:['To save money','Stopping when results look good inflates false positives','It is required by law','To use less data'],a:1,w:'"Peeking" biases the result.'},
  {q:'The median is better than the mean when…',o:['Data are symmetric','Data are skewed by outliers','Data are small','Always'],a:1,w:'E.g. salaries or deal sizes.'},
  {q:'A statistically significant 0.1% conversion lift…',o:['Must be launched','May not be worth the cost: check business significance','Proves causation forever','Is impossible'],a:1,w:'Size of effect matters as much as significance.'}],
 srs:[{q:'R²?',a:'Share of variance in y explained by the model; not causation.'},{q:'p-value?',a:'Probability of a result at least this extreme if there is no real effect.'},{q:'A/B test rules?',a:'Randomise, change one thing, fix sample size and stopping rule in advance.'},{q:'Simpson\'s paradox?',a:'A trend in groups reverses when the groups are combined.'}],
 read:[{t:'A Refresher on Regression Analysis',s:'Harvard Business Review, 2015',u:'https://hbr.org/2015/11/a-refresher-on-regression-analysis'},{t:'A Refresher on A/B Testing',s:'Harvard Business Review, 2017',u:'https://hbr.org/2017/06/a-refresher-on-ab-testing'},{t:'MIT OCW: statistics for applications',s:'MIT OpenCourseWare',u:OCW('statistics')}]}
]);
